fn solve(n: i8, s: Vec<char>) -> i8 {
    // Turn n into a usize for indexing.
    let len = n as usize;

    // If there's fewer than 2 characters, there are no adjacent pairs.
    if len < 2 {
        return 0;
    }

    let mut count: i8 = 0;
    // Scan from 0..len-1, comparing s[i] and s[i+1].
    for i in 0..(len - 1) {
        if s[i] == s[i + 1] {
            count += 1;
        }
    }

    count
}

